mapper.select:
SELECT id, workspace_id, name, created_at, updated_at
FROM workspace_role
WHERE workspace_id = #{workspaceId} AND id = #{id}

SELECT wrp.permission FROM workspace_role_permission wrp
JOIN workspace_role wr ON wr.id = wrp.workspace_role_id AND wr.workspace_id = #{workspaceId}
WHERE wrp.workspace_role_id = #{roleId}

mapper.delete:
DELETE wrp FROM workspace_role_permission wrp
JOIN workspace_role wr ON wr.id = wrp.workspace_role_id AND wr.workspace_id = #{workspaceId}
WHERE wrp.workspace_role_id = #{roleId}

mapper.select:
SELECT EXISTS(
  SELECT 1 FROM workspace_role WHERE workspace_id = #{workspaceId} AND id = #{id}
)
